"""Prepare alpha sprites generated by the installed IW ImageGen CLI."""
from pathlib import Path
import json
import numpy as np
from PIL import Image, ImageFilter, ImageDraw

ROOT = Path(__file__).resolve().parents[1]
ASSETS = ROOT / "assets" / "vd057-praise-3d"
READY = ASSETS / "ready"
READY.mkdir(parents=True, exist_ok=True)
NAMES = ["cool", "nice", "combo-x3", "combo-x5", "combo-x8", "fantastic", "unstoppable"]
rows = []
for name in NAMES:
    source = ASSETS / "generated" / f"{name}.png"
    image = Image.open(source).convert("RGBA")
    alpha = image.getchannel("A")
    if alpha.getextrema() != (0, 255):
        raise ValueError(f"Missing usable transparency: {source}")
    # Remove only tiny disconnected matte flecks; preserve the actual RGB art.
    core = alpha.point(lambda v: 255 if v >= 64 else 0)
    support = core.filter(ImageFilter.MinFilter(5)).filter(ImageFilter.MaxFilter(7))
    clean = np.asarray(alpha).copy()
    clean[np.asarray(support) == 0] = 0
    image.putalpha(Image.fromarray(clean))
    box = image.getchannel("A").getbbox()
    if not box or box[2] - box[0] < 400 or box[3] - box[1] < 100:
        raise ValueError(f"Blank or suspicious sprite: {source}")
    sprite = image.crop(box)
    pad = 24
    final = Image.new("RGBA", (sprite.width + pad*2, sprite.height + pad*2))
    final.alpha_composite(sprite, (pad, pad))
    out = READY / f"{name}.png"
    final.save(out)
    a = np.asarray(final.getchannel("A"))
    rows.append({"key": name, "source": str(source), "file": str(out), "width": final.width,
                 "height": final.height, "sourceSize": list(image.size), "alphaExtrema": list(final.getchannel("A").getextrema()),
                 "transparentFraction": float(np.mean(a == 0)), "crop": list(box), "padding": pad})

preview = Image.new("RGB", (1200, 1100), (87, 179, 62))
draw = ImageDraw.Draw(preview)
for i, row in enumerate(rows):
    x, y = (i % 2) * 600, (i // 2) * 265
    sprite = Image.open(row["file"])
    sprite.thumbnail((550, 205), Image.Resampling.LANCZOS)
    preview.paste(sprite, (x + (600-sprite.width)//2, y+35+(205-sprite.height)//2), sprite)
    draw.text((x+24, y+15), row["key"].upper(), fill=(255,255,255))
preview.save(ASSETS / "praise-3d-preview.jpg", quality=95)
manifest = {"model":"gpt-image-2.5-sunburst", "skill":"iw-imagegen", "promptFile":str(ROOT/".ae-codex/vd057-praise-imagegen-jobs.jsonl"),
            "assets":rows, "preview":str(ASSETS/"praise-3d-preview.jpg")}
(ROOT/".ae-codex/vd057-praise-assets.json").write_text(json.dumps(manifest,indent=2),encoding="utf-8")
print(json.dumps(manifest,indent=2))
